def route_visits(layout, params, ctx):
    import re
    pattern = re.compile(r"^([A-Za-z0-9]+)_V([0-9]+)_(.+)\.csv$")
    date = layout["vars"]["ds"]
    for path in layout["files"]:
        if path in layout["keys"]:
            continue
        name = path.rsplit("/", 1)[-1]
        m = pattern.match(name)
        if m:
            layout["keys"][path] = f"{date}/{m.group(1).lower()}/visit_{int(m.group(2))}/{name}"
    return layout

def route_unmatched(layout, params, ctx):
    date = layout["vars"]["ds"]
    for path in layout["files"]:
        if path in layout["keys"]:
            continue
        name = path.rsplit("/", 1)[-1]
        layout["keys"][path] = f"{date}/unmatched/{name}" if name.endswith(".csv") else None
    return layout
